import React from 'react';

export default function ActivityFeed({ activities }) {
  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200 h-full">
      <h2 className="text-lg font-semibold mb-3 text-gray-800">Recent Activity</h2>
      <ul className="space-y-2">
        {activities.length === 0 ? (
          <li className="text-sm text-gray-500">No recent activity.</li>
        ) : (
          activities.map((activity, i) => (
            <li key={i} className="text-sm text-gray-700">
              • {activity.text}
            </li>
          ))
        )}
      </ul>
    </div>
  );
}
